// nf-core modules test cellranger/mkgtf
nextflow_process {

    name "Test Process CELLRANGER_MKGTF"
    script "../main.nf"
    config "./nextflow.config"
    process "CELLRANGER_MKGTF"

    tag "modules"
    tag "modules_nfcore"
    tag "cellranger"
    tag "cellranger/mkgtf"

    test("homo_sapiens - reference") {

        when {
            process {
                """
                input[0] = [
                    [id: 'homo_sapiens'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }

    }

    test("homo_sapiens - reference - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [id: 'homo_sapiens'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }

    }

    test("homo_sapiens - identical input output names - stub") {

        options "-stub"

        when {
            params {
                module_prefix = 'genome'
            }
            process {
                """
                input[0] = [
                    [id: 'homo_sapiens'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.failed
            assert process.errorReport.contains("Input and output names are the same")
        }

    }

}
